@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Marcellus&display=swap');
:root{--ink:#f4efe4;--muted:#a9b5b4;--gold:#eab967;--cyan:#79d5d2;--panel:rgba(8,24,31,.83);--line:rgba(204,223,214,.14)}*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden;background:#071b26;color:var(--ink);font-family:'DM Sans',sans-serif}.game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#102e36}#game{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,19,25,.55),transparent 25%,transparent 60%,rgba(5,17,23,.46)),radial-gradient(ellipse at center,transparent 36%,rgba(4,17,22,.24) 100%)}.topbar{position:absolute;top:0;left:0;right:0;height:72px;padding:0 27px;display:flex;align-items:center;gap:12px;background:linear-gradient(180deg,rgba(5,18,23,.86),rgba(5,18,23,.28));border-bottom:1px solid rgba(255,255,255,.07)}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#f5eddf;font-family:Marcellus,serif;font-size:16px;letter-spacing:2px;line-height:1}.brand-mark{font-size:27px;color:var(--gold);text-shadow:0 0 16px #f4c679}.brand small{display:block;color:#89a1a0;font:9px 'DM Mono';letter-spacing:3px;margin-top:5px}.island-tag{margin:auto;display:flex;align-items:center;gap:10px;padding:9px 16px;border:1px solid rgba(231,231,211,.13);background:rgba(6,23,29,.54);border-radius:3px;color:#cad3c9;font:10px 'DM Mono';letter-spacing:1.2px}.island-tag i{color:#718785;font-style:normal}.live-dot{height:6px;width:6px;border-radius:50%;background:#79d5a5;box-shadow:0 0 8px #79d5a5}.icon-button{width:37px;height:37px;border:1px solid var(--line);border-radius:4px;background:rgba(9,24,30,.6);color:#e5e3d8;font-size:16px;cursor:pointer}.glass{background:var(--panel);border:1px solid var(--line);box-shadow:0 8px 32px #06141b46;backdrop-filter:blur(12px)}.player-card{position:absolute;top:89px;left:26px;width:258px;padding:14px;display:flex;gap:11px;border-radius:5px}.avatar{flex:none;width:39px;height:39px;display:grid;place-items:center;border:1px solid #bc9e62;border-radius:4px;background:linear-gradient(145deg,#334f4a,#172c34);color:#dfc17c;font-size:20px}.player-meta{flex:1;min-width:0}.name-row{display:flex;justify-content:space-between;align-items:center;font-size:10px;letter-spacing:.8px;margin:1px 0 10px}.name-row span,.quest-rank{color:#e9bd73;font:10px 'DM Mono';padding:3px 5px;background:#d9a95320;border:1px solid #d9a9533c;border-radius:2px}.bar-label{display:flex;justify-content:space-between;margin:6px 0 3px;color:#98aaa8;font:8px 'DM Mono';letter-spacing:.8px}.bar-label span:last-child{color:#d7dfd8}.meter{height:4px;background:#ffffff16;border-radius:4px;overflow:hidden}.meter i{display:block;height:100%;width:100%;transition:width .2s;border-radius:4px}.health i{background:linear-gradient(90deg,#d86f58,#efa37d)}.stamina i{background:linear-gradient(90deg,#45a99c,#79dfc6)}.xp i{background:linear-gradient(90deg,#ddad60,#f0d484)}.xp-label{margin-top:7px}.quest-card{position:absolute;top:89px;right:26px;width:248px;padding:15px 16px 13px;border-radius:5px}.panel-kicker{display:flex;justify-content:space-between;align-items:center;font:9px 'DM Mono';letter-spacing:1.2px;color:#d9b66f}.quest-rank{padding:2px 6px}.quest-card h2{font:18px Marcellus,serif;margin:12px 0 6px;color:#f0e9d8}.quest-card p{color:#a6b1ad;font-size:10px;line-height:1.6;margin:0 0 13px}.quest-progress{display:flex;align-items:center;gap:9px;color:#d6d5c9;font:9px 'DM Mono';margin-bottom:13px}.progress-track{height:4px;background:#ffffff1a;flex:1;border-radius:3px}.progress-track i{height:100%;display:block;width:0;background:#e6b964;transition:width .3s}.quest-reward{display:flex;align-items:center;gap:11px;padding:9px 0;border-top:1px solid #ffffff12;color:#d8dfd7;font:9px 'DM Mono'}.quest-reward>span{color:#819692;margin-right:auto}.quest-reward b{color:#efd087;font-weight:500}.quest-reward small{font-size:8px;color:#a6b1ad}.small-button{width:100%;height:28px;background:#e5b867;color:#1c2929;border:0;border-radius:2px;font:9px 'DM Mono';letter-spacing:.9px;cursor:pointer}.small-button span{float:right;font-size:13px;margin-top:-3px}.currency{position:absolute;right:26px;top:343px;display:flex;align-items:center;gap:8px;padding:8px 12px;border-radius:4px}.currency>span:not(.divider){font-size:15px}.currency .coin{color:#edc267}.currency .gem{color:#8ed1c8}.currency small,.currency b{display:block}.currency small{font:8px 'DM Mono';letter-spacing:1px;color:#92a6a2}.currency b{font:12px 'DM Mono';color:#f1e4c4;margin-top:2px}.divider{height:23px;border-left:1px solid #ffffff1b;margin:0 5px}.objective-toast{position:absolute;top:44%;left:50%;transform:translate(-50%,-50%);display:flex;gap:9px;align-items:center;padding:11px 16px;background:rgba(6,21,26,.76);border:1px solid #dcb36350;color:#edcf8b;font:10px 'DM Mono';letter-spacing:.6px;opacity:0;transition:opacity .4s;pointer-events:none}.objective-toast.show{opacity:1}.objective-toast>span:first-child{font-size:18px}.interact-hint{position:absolute;bottom:127px;left:50%;transform:translateX(-50%);display:none;align-items:center;gap:9px;padding:8px 13px;background:#06171de0;border:1px solid #e7c67970;border-radius:3px;color:#e9e3d4;font-size:11px}.interact-hint.visible{display:flex}kbd{padding:3px 6px;color:#f0c877;background:#b8903a28;border:1px solid #d9af5d66;border-radius:2px;font:10px 'DM Mono'}.hotbar{position:absolute;bottom:42px;left:50%;transform:translateX(-50%);height:70px;display:flex;gap:6px;padding:7px;border-radius:5px}.skill{position:relative;width:119px;height:54px;padding:6px 8px 5px 45px;text-align:left;background:rgba(21,41,46,.76);border:1px solid rgba(255,255,255,.09);border-radius:3px;color:#eff0e5;cursor:pointer;transition:background .15s,transform .15s}.skill:hover{background:#324a49;transform:translateY(-2px)}.skill.basic{width:111px}.skill-icon{position:absolute;left:9px;top:9px;width:29px;height:29px;display:grid;place-items:center;border-radius:4px;background:linear-gradient(145deg,#526a61,#263b3d);color:#e8c67a;font-size:18px}.fruit-icon{color:#6ed7ca;text-shadow:0 0 9px #67d7c68c;background:linear-gradient(145deg,#244f50,#172f39)}.fruit-icon.violet{color:#c7a6fa;text-shadow:0 0 9px #9670cf99;background:linear-gradient(145deg,#423450,#26293b)}.dash-icon{font-size:20px;color:#aad5cd}.key{display:block;color:#e0bb70;font:9px 'DM Mono';letter-spacing:.5px;margin-bottom:3px}.skill-name{display:block;font-size:10px;font-weight:600;white-space:nowrap}.skill-cost{display:block;color:#8da39f;font:8px 'DM Mono';margin-top:3px}.cooldown{position:absolute;inset:0;background:#101b20b8;transform:scaleY(0);transform-origin:bottom;pointer-events:none}.controls-note{position:absolute;bottom:17px;left:50%;transform:translateX(-50%);color:#a3b2ac;font:8px 'DM Mono';letter-spacing:1px;white-space:nowrap;text-shadow:0 1px 4px #000}.controls-note span{color:#e1c47e}.controls-note i{font-style:normal;color:#586b68;margin:0 8px}.modal{color:var(--ink);width:min(440px,calc(100vw - 28px));padding:0;border-radius:6px;background:rgba(8,24,31,.96);border:1px solid rgba(213,190,130,.35);box-shadow:0 22px 90px #0009}.modal::backdrop{background:#0411179c;backdrop-filter:blur(4px)}.modal-content{padding:30px}.close-modal{position:absolute;right:13px;top:10px;background:none;border:0;color:#aeb8af;font-size:23px;cursor:pointer}.modal h2{font:26px Marcellus,serif;color:#f0d291;margin:0 0 12px}.modal p{font-size:13px;line-height:1.7;color:#b9c3bc}.modal .accent{color:#edc675}.modal-actions{display:flex;gap:9px;margin-top:22px}.modal-actions button{flex:1;padding:12px;background:#e5b867;border:0;border-radius:3px;color:#1d2b2c;font:10px 'DM Mono';letter-spacing:.5px;cursor:pointer}.modal-actions button.secondary{background:#20373b;color:#e0e2d7;border:1px solid #ffffff1c}.damage-flash{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse,transparent 45%,#d94f4a70);opacity:0;transition:opacity .1s}.damage-flash.hit{opacity:1}.mobile-controls{display:none}
@media(max-width:720px){.topbar{height:57px;padding:0 12px}.brand{font-size:12px;gap:7px}.brand-mark{font-size:21px}.brand small{font-size:7px}.island-tag{font-size:8px;gap:6px;padding:7px 8px;letter-spacing:.3px}.icon-button{width:31px;height:31px}.player-card{top:68px;left:10px;width:205px;padding:9px;gap:8px}.avatar{width:32px;height:32px;font-size:16px}.name-row{font-size:8px;margin-bottom:6px}.quest-card{top:68px;right:10px;width:190px;padding:10px}.quest-card h2{font-size:15px;margin:7px 0 4px}.quest-card p{font-size:9px;line-height:1.35;margin-bottom:8px}.quest-progress{margin-bottom:8px}.quest-reward{gap:7px;padding:6px 0}.small-button{height:25px;font-size:8px}.currency{right:10px;top:273px;padding:6px 9px}.objective-toast{top:48%;max-width:90%;white-space:nowrap}.hotbar{bottom:14px;left:50%;height:56px;padding:5px;gap:4px}.skill,.skill.basic{width:82px;height:44px;padding:5px 3px 3px 34px}.skill-icon{left:5px;top:8px;width:24px;height:26px;font-size:15px}.skill-name{font-size:8px}.skill-cost{font-size:7px;margin-top:2px}.key{font-size:8px;margin-bottom:2px}.controls-note{display:none}.interact-hint{bottom:80px}.mobile-controls{display:block}.dpad{position:absolute;left:13px;bottom:19px;width:114px;height:104px;pointer-events:none}.dpad button{pointer-events:auto;background:#10282bbd;border:1px solid #dce8d044;color:#f4e3b7;border-radius:9px;width:36px;height:34px;font-size:14px;touch-action:none}.dpad>button{position:absolute;left:39px;top:0}.dpad div{position:absolute;bottom:0;left:0;right:0;display:flex;justify-content:space-between}.dpad div button:nth-child(2){position:absolute;left:39px;top:0}.mobile-action{position:absolute;right:14px;bottom:30px;width:55px;height:55px;border-radius:50%;border:1px solid #ecd18d88;background:#453e2cdd;color:#f2d785;font-size:19px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;touch-action:none}.mobile-action small{font:7px 'DM Mono'}.fruit-action{right:76px;bottom:18px;width:45px;height:45px;font-size:15px;background:#183c3bdc;border-color:#76d5c488;color:#80dece}.hotbar{bottom:14px;transform:translateX(-50%);margin-bottom:112px}.vignette{background:linear-gradient(180deg,rgba(5,19,25,.5),transparent 25%,transparent 65%,rgba(5,17,23,.35)),radial-gradient(ellipse at center,transparent 35%,rgba(4,17,22,.18) 100%)}}
@media(max-width:420px){.quest-card{width:165px}.quest-card p{font-size:8px}.player-card{width:176px}.currency{top:263px}.hotbar{gap:2px}.skill,.skill.basic{width:73px;padding-left:31px}.skill-icon{left:4px;width:22px}.island-tag{margin-left:auto;margin-right:0}.brand{margin-right:auto}}

(() => {
  'use strict';
  const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
  const $=s=>document.querySelector(s),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  let W=0,H=0,dpr=1,last=0,worldTime=0,toastTimer=0,shake=0;
  const map={w:2200,h:1500,cx:1100,cy:760};
  const player={x:1090,y:830,r:17,hp:100,maxHp:100,energy:100,maxEnergy:100,xp:0,level:1,gold:250,shards:0,dir:0,speed:210,attackCd:0,skill1:0,skill2:0,dashCd:0,invuln:0,flash:0};
  const keeper={x:1065,y:690};
  let quest={active:false,kills:0,done:false};
  const enemies=[];for(let i=0;i<8;i++){const a=i*Math.PI/4+.2;enemies.push({x:map.cx+Math.cos(a)* (330+(i%3)*80),y:map.cy+Math.sin(a)*(250+(i%2)*90),r:16,hp:52,maxHp:52,alive:true,respawn:0,attack:0,hit:0,phase:Math.random()*6,variant:i%3});}
  const palms=[[-230,-120],[-110,-230],[60,-290],[240,-250],[390,-160],[510,-10],[460,150],[330,260],[170,320],[-30,300],[-230,240],[-410,160],[-490,-10],[-400,-180],[50,60],[470,260],[-500,300],[560,-190]];
  const rocks=[[-150,-60],[300,100],[-340,40],[70,-160],[530,75],[-360,-260],[250,350]];
  const decor=[];let seed=98473;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}for(let i=0;i<380;i++){const a=rand()*Math.PI*2,r=160+rand()*540;decor.push({x:map.cx+Math.cos(a)*r,y:map.cy+Math.sin(a)*r,kind:rand(),scale:.5+rand()*.8});}
  function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
  const keys=new Set(),mobile=new Set();let mouse={x:W/2,y:H/2,down:false};
  function toast(text){$('#toast-message').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
  function ui(){const p=player;$('#level').textContent='LV. '+p.level;$('#health-text').textContent=Math.ceil(p.hp)+' / '+p.maxHp;$('#stamina-text').textContent=Math.ceil(p.energy)+' / '+p.maxEnergy;$('#health-fill').style.width=(p.hp/p.maxHp*100)+'%';$('#stamina-fill').style.width=(p.energy/p.maxEnergy*100)+'%';$('#xp-text').textContent=p.xp+' / '+(100+(p.level-1)*70);$('#xp-fill').style.width=(p.xp/(100+(p.level-1)*70)*100)+'%';$('#gold').textContent=p.gold;$('#shards').textContent=p.shards;$('#quest-count').textContent=quest.kills+' / 3';$('#quest-fill').style.width=Math.min(100,quest.kills/3*100)+'%';$('#quest-title').textContent=quest.done?'Bounty Complete':quest.active?'Cove Clean-up':'A Sailor’s First Bounty';$('#quest-desc').textContent=quest.done?'You have earned the cove’s gratitude. The keeper has another challenge when you are ready.':quest.active?'Defeat 3 cove bandits and return to the Bounty Keeper.':'Speak with the Bounty Keeper to accept your first bounty.';$('#quest-button').textContent=quest.done?'CLAIM REWARD  ✦':quest.active?'TRACK BOUNTY  ↗':'ACCEPT BOUNTY  ↗'}
  function camera(){return{x:clamp(player.x-W/2,0,map.w-W),y:clamp(player.y-H/2,0,map.h-H)}}
  function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
  function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
  function pathIsland(cx,cy,rx,ry){ctx.beginPath();for(let i=0;i<=140;i++){let a=i/140*Math.PI*2;let n=1+.045*Math.sin(a*5+.6)+.027*Math.sin(a*9+1);let x=cx+Math.cos(a)*rx*n,y=cy+Math.sin(a)*ry*n;if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath()}
  function drawWater(cam){const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#1d6770');g.addColorStop(.45,'#165563');g.addColorStop(1,'#0e3547');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.save();ctx.translate(-cam.x,-cam.y);let t=worldTime;for(let i=0;i<90;i++){const x=((i*197+Math.sin(t*.23+i)*48)%map.w+map.w)%map.w,y=((i*317+Math.cos(t*.17+i*2)*40)%map.h+map.h)%map.h;ctx.strokeStyle=`rgba(177,229,210,${.045+.035*Math.sin(t+i)})`;ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(x,y,18+(i%6)*5,3+(i%3),-.12,0,Math.PI*2);ctx.stroke()}ctx.restore();}
  function drawIsland(cam){ctx.save();ctx.translate(-cam.x,-cam.y);const cx=map.cx,cy=map.cy;
    pathIsland(cx+12,cy+18,670,500);ctx.fillStyle='#153e3d';ctx.fill();pathIsland(cx,cy,654,487);ctx.fillStyle='#d5bc83';ctx.fill();pathIsland(cx,cy-7,612,450);const grass=ctx.createLinearGradient(cx-450,cy-360,cx+420,cy+400);grass.addColorStop(0,'#758b5c');grass.addColorStop(.55,'#577654');grass.addColorStop(1,'#466b54');ctx.fillStyle=grass;ctx.fill();
    // meadows, paths, and settled clearing
    ctx.fillStyle='rgba(185,168,113,.8)';ctx.beginPath();ctx.moveTo(cx+20,cy+70);ctx.bezierCurveTo(cx-40,cy-40,cx-120,cy-130,cx-80,cy-235);ctx.bezierCurveTo(cx-48,cy-318,cx+60,cy-330,cx+120,cy-290);ctx.bezierCurveTo(cx+170,cy-245,cx+90,cy-170,cx+135,cy-96);ctx.bezierCurveTo(cx+190,cy-30,cx+145,cy+30,cx+20,cy+70);ctx.fill();ctx.strokeStyle='rgba(239,223,174,.22)';ctx.lineWidth=15;ctx.stroke();
    ellipse(cx-210,cy-150,155,105,'#647f57');ellipse(cx+300,cy+15,145,124,'#567b57');ellipse(cx+20,cy+245,170,95,'#607e57');ellipse(cx-10,cy-8,195,140,'#71875b');
    // rocks, foliage detail
    decor.forEach(d=>{const edge=Math.pow((d.x-cx)/650,2)+Math.pow((d.y-cy)/470,2);if(edge>.78&&edge<1.04){if(d.kind>.48){ellipse(d.x,d.y,4*d.scale,2.7*d.scale,'rgba(249,231,184,.62)')}else ellipse(d.x,d.y,3*d.scale,4*d.scale,'rgba(42,91,67,.4)')}});
    rocks.forEach(([ox,oy],i)=>{const x=cx+ox,y=cy+oy;ellipse(x+3,y+8,18,8,'#314b40');ellipse(x,y,15+i%3*3,11+i%2*4,'#7b8170');ellipse(x-4,y-4,7,3,'#a2a08a')});
    // village huts
    hut(cx-125,cy-225,1);hut(cx+90,cy-235,.82);hut(cx+155,cy-150,.7);
    // docks
    ctx.fillStyle='#795b3e';for(let i=0;i<7;i++){rounded(cx-15+i*8,cy+422,6,150,1,i%2?'#9b7952':'#846746')}for(let i=0;i<3;i++){rounded(cx-27,cy+438+i*48,70,7,1,'#ad895e')}ctx.fillStyle='#aa8960';rounded(cx-20,cy+411,62,18,2,'#b19165');
    // palms
    palms.forEach(([ox,oy],i)=>palm(cx+ox,cy+oy,i));
    // bounty marker
    ctx.save();ctx.translate(keeper.x,keeper.y);const pulse=1+Math.sin(worldTime*2.7)*.09;ctx.strokeStyle='rgba(242,198,111,.58)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-38,15*pulse,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#f0cb79';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillText('!',0,-34);ctx.restore();
    ctx.restore();}
  function hut(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ellipse(0,23,48,13,'#385246');ctx.fillStyle='#bc8e5c';ctx.fillRect(-34,-8,68,31);ctx.fillStyle='#443d32';ctx.beginPath();ctx.moveTo(-44,-6);ctx.lineTo(0,-43);ctx.lineTo(43,-6);ctx.closePath();ctx.fill();ctx.fillStyle='#796045';ctx.fillRect(-7,1,15,22);ctx.fillStyle='#e7c780';ctx.fillRect(17,0,9,10);ctx.restore()}
  function palm(x,y,i){ctx.save();ctx.translate(x,y);const s=.78+(i%4)*.1;ctx.scale(s,s);ellipse(5,13,16,8,'#304b40');ctx.strokeStyle='#756647';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(0,12);ctx.quadraticCurveTo(-5,-8,2,-33);ctx.stroke();ctx.strokeStyle='#a18a5a';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,8);ctx.quadraticCurveTo(-4,-10,2,-32);ctx.stroke();for(let k=0;k<7;k++){let a=k*Math.PI/3.5;ctx.fillStyle=k%2?'#315f4c':'#3e704e';ctx.beginPath();ctx.ellipse(2+Math.cos(a)*25,-34+Math.sin(a)*17,26,6,a,0,Math.PI*2);ctx.fill()}ellipse(2,-34,6,5,'#8e9255');ctx.restore()}
  function drawChar(x,y,kind,dir,hit=0){ctx.save();ctx.translate(x,y);if(hit>0)ctx.globalAlpha=.6+.4*Math.sin(hit*26);ellipse(1,13,17,7,'#10272177');if(kind==='player'){ctx.save();ctx.rotate(dir);ctx.fillStyle='#aa8b52';ctx.fillRect(6,-2,25,4);ctx.fillStyle='#d8d8c8';ctx.beginPath();ctx.moveTo(29,-2);ctx.lineTo(37,0);ctx.lineTo(29,2);ctx.fill();ctx.restore();ellipse(0,3,11,13,'#b8d1c2');ctx.fillStyle='#263e42';ctx.beginPath();ctx.moveTo(-12,0);ctx.lineTo(-8,-11);ctx.lineTo(8,-11);ctx.lineTo(12,2);ctx.lineTo(8,11);ctx.lineTo(-8,11);ctx.fill();ctx.fillStyle='#d7bd7d';ctx.fillRect(-9,-7,18,5);ellipse(0,-11,8,7,'#b7815d');ctx.fillStyle='#29393a';ctx.beginPath();ctx.moveTo(-9,-14);ctx.lineTo(0,-23);ctx.lineTo(9,-14);ctx.closePath();ctx.fill();ctx.fillStyle='#f4ddaa';ctx.fillRect(-2,-12,5,2);}
